<?php
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../config/db.php';
require_once __DIR__ . '/../includes/admin_ui.php';
if (!isLoggedIn() || getUserRole() !== 'admin') { header('Location: ' . appUrl('login.php')); exit; }
$summary = $conn->query("SELECT COALESCE(SUM(amount),0) AS total_revenue, COALESCE(SUM(CASE WHEN YEAR(created_at)=YEAR(CURRENT_DATE()) AND MONTH(created_at)=MONTH(CURRENT_DATE()) THEN amount ELSE 0 END),0) AS monthly_revenue FROM platform_earnings")->fetch_assoc();
$earnings = $conn->query("SELECT pe.id, p.title AS project_title, pe.amount, pe.created_at FROM platform_earnings pe INNER JOIN projects p ON p.id = pe.project_id ORDER BY pe.created_at DESC, pe.id DESC");
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Platform Revenue</title><link rel="stylesheet" href="<?php echo htmlspecialchars(appUrl('assets/css/style.css')); ?>"><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f4f7fb;color:#1f2937}a{text-decoration:none}.admin-layout{min-height:100vh;display:flex}.sidebar{width:260px;background:#111827;color:#fff;padding:24px 18px}.brand{font-size:24px;font-weight:700;margin-bottom:8px}.brand-subtitle{color:#9ca3af;font-size:14px;margin-bottom:26px}.nav-link{display:block;color:#d1d5db;padding:12px 14px;border-radius:10px;margin-bottom:8px}.nav-link:hover,.nav-link.active{background:#2563eb;color:#fff}.sidebar-section{margin-bottom:20px}.sidebar-heading{color:#6b7280;font-size:11px;font-weight:700;letter-spacing:.12em;margin:0 0 10px 12px}.content{flex:1;padding:28px}.topbar{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px;flex-wrap:wrap}.page-title{margin:0;font-size:30px}.topbar-text{margin:6px 0 0;color:#6b7280}.logout-btn{background:#dc2626;color:#fff;padding:10px 16px;border-radius:10px;font-weight:600}.stats-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-bottom:24px}.panel,.stat-card{background:#fff;border-radius:16px;padding:22px;box-shadow:0 12px 30px rgba(15,23,42,.08)}.stat-card h3{margin:0 0 10px;color:#6b7280;font-size:15px;font-weight:600}.value{font-size:34px;font-weight:700}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:14px 12px;border-bottom:1px solid #e5e7eb}th{color:#6b7280;font-size:13px;text-transform:uppercase;letter-spacing:.04em}tbody tr:hover{background:#f8fbff}.empty-state{color:#6b7280;margin:0}</style></head><body><div class="admin-layout"><?php renderAdminSidebar('revenue'); ?><main class="content"><div class="topbar"><div><h1 class="page-title">Platform Revenue</h1><p class="topbar-text">Track commissions earned from approved marketplace work.</p></div><a class="logout-btn" href="<?php echo htmlspecialchars(appUrl('admin/logout.php')); ?>">Logout</a></div><section class="stats-grid"><div class="stat-card"><h3>Total Revenue</h3><div class="value">$<?php echo number_format((float) $summary['total_revenue'], 2); ?></div></div><div class="stat-card"><h3>Monthly Revenue</h3><div class="value">$<?php echo number_format((float) $summary['monthly_revenue'], 2); ?></div></div></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>ID</th><th>Project</th><th>Amount</th><th>Created</th></tr></thead><tbody><?php if ($earnings->num_rows > 0): while ($earning = $earnings->fetch_assoc()): ?><tr><td><?php echo (int) $earning['id']; ?></td><td><?php echo htmlspecialchars($earning['project_title']); ?></td><td>$<?php echo number_format((float) $earning['amount'], 2); ?></td><td><?php echo htmlspecialchars($earning['created_at']); ?></td></tr><?php endwhile; else: ?><tr><td colspan="4"><p class="empty-state">No revenue yet. Platform commissions will start appearing here once approved projects lead to successful hires.</p></td></tr><?php endif; ?></tbody></table></div></section></main></div></body></html>
